descriptor.controllerScript:
var tgMapFrame;
var tgLastFrameKey = '';
var tgLastFrameUpdate = 0;

function tgLatestValue(name) {
  var rows = self.ctx.data || [];
  for (var i = 0; i < rows.length; i++) {
    var row = rows[i];
    if (!row.dataKey || row.dataKey.name !== name || !row.data || !row.data.length) {
      continue;
    }
    var newest = row.data[0];
    for (var j = 1; j < row.data.length; j++) {
      if (row.data[j][0] > newest[0]) { newest = row.data[j]; }
    }
    return newest[1];
  }
  return null;
}

function tgAsBoolean(value) {
  return value === true || value === 1 || value === '1' || value === 'true';
}

function tgRenderMap(force) {
  var scope = self.ctx.$scope;
  var latitude = Number(tgLatestValue('latitude'));
  var longitude = Number(tgLatestValue('longitude'));
  var speed = Number(tgLatestValue('speed_kmh'));
  var satellites = Number(tgLatestValue('satellites'));
  var gpsState = tgLatestValue('gps_state');
  var current = tgAsBoolean(tgLatestValue('position_current'));
  var valid = Number.isFinite(latitude) && Number.isFinite(longitude) &&
      latitude >= -90 && latitude <= 90 && longitude >= -180 && longitude <= 180 &&
      !(latitude === 0 && longitude === 0);

  scope.hasPosition = valid;
  scope.latitudeText = valid ? latitude.toFixed(7) : '--';
  scope.longitudeText = valid ? longitude.toFixed(7) : '--';
  scope.speedText = Number.isFinite(speed) ? speed.toFixed(1) + ' km/h' : '--';
  scope.satellitesText = Number.isFinite(satellites) ? String(Math.round(satellites)) : '--';
  scope.positionText = valid ? (current ? 'MỚI' : 'CŨ') : 'CHƯA CÓ';
  scope.positionClass = valid && current ? 'fresh' : 'stale';
  scope.status = valid ? ('GPS ' + (gpsState || 'đã có tọa độ')) : ('GPS ' + (gpsState || 'đang chờ fix'));

  if (valid && tgMapFrame) {
    var refreshMs = Math.max(2000, Number(self.ctx.settings.mapRefreshMs || 5000));
    var delta = Math.max(0.001, Number(self.ctx.settings.mapSpanDegrees || 0.01));
    var frameKey = latitude.toFixed(5) + ',' + longitude.toFixed(5);
    var now = Date.now();
    if (force || (frameKey !== tgLastFrameKey && now - tgLastFrameUpdate >= refreshMs)) {
      var bbox = [longitude - delta, latitude - delta, longitude + delta, latitude + delta]
        .map(function(v) { return v.toFixed(7); }).join('%2C');
      tgMapFrame.src = 'https://www.openstreetmap.org/export/embed.html?bbox=' + bbox +
        '&layer=mapnik&marker=' + latitude.toFixed(7) + '%2C' + longitude.toFixed(7);
      tgMapFrame.style.display = 'block';
      tgLastFrameKey = frameKey;
      tgLastFrameUpdate = now;
    }
  } else if (tgMapFrame) {
    tgMapFrame.style.display = 'none';
  }

  scope.openExternalMap = function() {
    if (!scope.hasPosition) { return; }
    window.open('https://www.openstreetmap.org/?mlat=' + latitude.toFixed(7) +
      '&mlon=' + longitude.toFixed(7) + '#map=17/' + latitude.toFixed(7) + '/' +
      longitude.toFixed(7), '_blank', 'noopener,noreferrer');
  };
  if (scope.$evalAsync) { scope.$evalAsync(); }
}

self.onInit = function() {
  var root = self.ctx.$container && self.ctx.$container[0];
  tgMapFrame = root ? root.querySelector('.tg-map-frame') : null;
  tgRenderMap(true);
};

self.onDataUpdated = function() {
  tgRenderMap(false);
};

self.typeParameters = function() {
  return {
    maxDatasources: 1,
    dataKeysOptional: false,
    singleEntity: true,
    previewWidth: '900px',
    previewHeight: '480px'
  };
};

self.onDestroy = function() {
  if (tgMapFrame) { tgMapFrame.src = 'about:blank'; }
};
